        if (address(_oracles[oracleId]) != address(0)) {
            revert OracleAlreadyExists(
                pool,
                shouldUseBlockTimeForOldestFeedUpdate,
                shouldRevertIfVaultUnlocked,
                feeds,
                _oracles[oracleId]
