function _computeTVL(int256[] memory prices) internal view override returns (uint256 tvl) {





        int256[] memory normalizedPrices = _ensureValidPricesAndNormalize(prices);









        uint256[] memory currentBalancesLiveScaled18 = _vault.getCurrentLiveBalances(address(pool));
        uint256 invariant = pool.computeInvariant(currentBalancesLiveScaled18, Rounding.ROUND_DOWN);

        uint256[] memory marketPriceBalancesScaled18 = _computeMarketPriceBalances(invariant, normalizedPrices);

        for (uint256 i = 0; i < _totalTokens; i++) {
            tvl += prices[i].toUint256().mulDown(marketPriceBalancesScaled18[i]);
        }

        return tvl;
